@startuml

class Bettor {
  + Name : string
}

class Race {
  + NumberOfRunners : int
}

class Runner {
  + Name : string
}

class Jockey {
  + Name : string
}

class Bet {
  + Amount : float
  + Odds : float
}

Bettor "1" -- "*" Bet : places
Bet "*" -- "1" Race : refers to
Bet "*" -- "1" Runner : on
Race "1" -- "1" Runner : winner
Runner "*" -- "1" Jockey : is ridden by
Race "1" -- "1..*" Runner : has

@enduml

